pub fn strange_sort_list_helper(s: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    let mut v = s;                        // first result = the original list
    let n = v.len();
    let mut t = Vec::with_capacity(n);    // second result: the interleaving

    // build t[i] = if i even, v[i/2]; else v[n - ((i-1)/2) - 1]
    for i in 0..n {
        if i % 2 == 0 {
            t.push(v[i / 2]);
        } else {
            t.push(v[n - ((i - 1) / 2) - 1]);
        }
    }

    (v, t)
}